#!/usr/bin/env bash
# SEIR Foundations Lab 4: network-only teardown. Bash 4+ and AWS CLI v2.
set -Eeuo pipefail
export AWS_PAGER=""
STATE_FILE=${1:-balerica-network.env}
fail() { echo "STOP: $*" >&2; exit 1; }
trap 'echo "Teardown stopped at line $LINENO. State retained; inspect AWS before retrying." >&2' ERR
command -v aws >/dev/null || fail 'AWS CLI required'
[[ -f "$STATE_FILE" ]] || fail "Missing $STATE_FILE"
# Parse only simple assignments generated by the lab; never execute the file.
declare -A state=()
while IFS= read -r line || [[ -n "$line" ]]; do
  [[ -z "$line" ]] && continue
  [[ "$line" =~ ^([A-Z][A-Z0-9_]*)=([a-zA-Z0-9./_-]+)$ ]] || fail "Unexpected state file format"
  state[${BASH_REMATCH[1]}]=${BASH_REMATCH[2]}
done < "$STATE_FILE"
region=${state[AWS_REGION]:-}; vpc=${state[VPC_ID]:-}; cidr=${state[VPC_CIDR]:-}
[[ "$region" == us-east-1 && "$vpc" =~ ^vpc-[0-9a-f]+$ && "$cidr" =~ ^10\.[0-9]{1,3}\.0\.0/16$ ]] || fail 'Invalid region, VPC ID or lab CIDR'
export AWS_REGION="$region" AWS_DEFAULT_REGION="$region"
# Explicit region on every call avoids profile or environment ambiguity.
a() { aws --region "$region" "$@"; }
account=$(a sts get-caller-identity --query Account --output text)
read -r actual default name owner <<< "$(a ec2 describe-vpcs --vpc-ids "$vpc" --query 'Vpcs[0].[CidrBlock,IsDefault,Tags[?Key==`Name`]|[0].Value,OwnerId]' --output text)"
[[ "$default" == False && "$actual" == "$cidr" && "$owner" == "$account" && "$name" == *-vpc ]] || fail 'VPC identity mismatch or default VPC. Chewbacca says NO.'
project=${name%-vpc}
[[ "$(basename "$STATE_FILE")" == "$project-network.env" ]] || fail 'State filename and VPC name do not match'
filter="Name=vpc-id,Values=$vpc"
# Refuse live application resources, including stopped instances and managed ENIs.
check_empty() { local count; count=$(a "$@" --output text); [[ "$count" == 0 ]] || fail "Dependencies found: $* ($count). Remove separately."; }
check_empty ec2 describe-instances --filters "$filter" 'Name=instance-state-name,Values=pending,running,stopping,stopped,shutting-down' --query 'length(Reservations[].Instances[])'
check_empty ec2 describe-network-interfaces --filters "$filter" --query 'length(NetworkInterfaces)'
check_empty ec2 describe-nat-gateways --filter "$filter" 'Name=state,Values=pending,available,deleting,failed' --query 'length(NatGateways)'
check_empty ec2 describe-vpc-endpoints --filters "$filter" --query 'length(VpcEndpoints)'
check_empty ec2 describe-security-groups --filters "$filter" --query 'length(SecurityGroups[?GroupName!=`default`])'
check_empty ec2 describe-network-acls --filters "$filter" --query 'length(NetworkAcls[?IsDefault==`false`])'
check_empty rds describe-db-subnet-groups --query "length(DBSubnetGroups[?VpcId=='$vpc'])"
# Inventory must match recorded IDs. Unknown resources are never swept up.
contains() { local needle=$1; shift; local x; for x in "$@"; do [[ "$x" == "$needle" ]] && return 0; done; return 1; }
subnets=(); tables=(); associations=()
for tier in PUBLIC PRIVATE1 PRIVATE2; do
  rt=${state[${tier}_RT_ID]:-}; [[ -z "$rt" || "$rt" =~ ^rtb-[0-9a-f]+$ ]] || fail 'Invalid route table ID'; [[ -z "$rt" ]] || tables+=("$rt")
  for az in A B C; do
    id=${state[${tier}_${az}_ID]:-}; [[ -z "$id" || "$id" =~ ^subnet-[0-9a-f]+$ ]] || fail 'Invalid subnet ID'; [[ -z "$id" ]] || subnets+=("$id")
    id=${state[${tier}_${az}_ASSOC_ID]:-}; [[ -z "$id" || "$id" =~ ^rtbassoc-[0-9a-f]+$ ]] || fail 'Invalid association ID'; [[ -z "$id" ]] || associations+=("$id")
  done
done
live_subnets=$(a ec2 describe-subnets --filters "$filter" --query 'Subnets[].SubnetId' --output text)
live_tables=$(a ec2 describe-route-tables --filters "$filter" --query 'RouteTables[?!Associations[?Main==`true`]].RouteTableId' --output text)
live_assoc=$(a ec2 describe-route-tables --filters "$filter" --query 'RouteTables[].Associations[?Main==`false`].RouteTableAssociationId[]' --output text)
for id in $live_subnets; do contains "$id" "${subnets[@]}" || fail "Unrecorded subnet $id"; done
for id in $live_tables; do contains "$id" "${tables[@]}" || fail "Unrecorded route table $id"; done
for id in $live_assoc; do contains "$id" "${associations[@]}" || fail "Unrecorded association $id"; done
igw=${state[IGW_ID]:-}
[[ -z "$igw" || "$igw" =~ ^igw-[0-9a-f]+$ ]] || fail 'Invalid IGW ID'
live_igw=$(a ec2 describe-internet-gateways --filters "Name=attachment.vpc-id,Values=$vpc" --query 'InternetGateways[].InternetGatewayId' --output text)
[[ -z "$live_igw" || "$live_igw" == "$igw" ]] || fail 'Unrecorded Internet Gateway'
printf 'Account: %s\nRegion: %s\nVPC: %s (%s, %s)\nSubnets: %s\nRoute tables: %s\nIGW: %s\n' "$account" "$region" "$vpc" "$name" "$cidr" "$live_subnets" "$live_tables" "$live_igw"
read -r -p "Type DELETE $vpc to proceed: " confirmation
[[ "$confirmation" == "DELETE $vpc" ]] || fail 'Cancelled; no resources deleted'
for id in $live_assoc; do a ec2 disassociate-route-table --association-id "$id"; done
for id in $live_subnets; do a ec2 delete-subnet --subnet-id "$id"; done
for id in $live_tables; do a ec2 delete-route-table --route-table-id "$id"; done
if [[ -n "$live_igw" ]]; then
  a ec2 detach-internet-gateway --internet-gateway-id "$live_igw" --vpc-id "$vpc"
  a ec2 delete-internet-gateway --internet-gateway-id "$live_igw"
elif [[ -n "$igw" ]]; then
  echo "Inspect recorded IGW $igw separately if a previous run detached it."
fi
a ec2 delete-vpc --vpc-id "$vpc"
remaining=$(a ec2 describe-vpcs --filters "Name=vpc-id,Values=$vpc" --query 'length(Vpcs)' --output text)
[[ "$remaining" == 0 ]] || fail 'VPC deletion not yet verified'
archive="${STATE_FILE}.deleted.$(date -u +%Y%m%dT%H%M%SZ)"
mv -n -- "$STATE_FILE" "$archive"
echo "VPC deleted and verified. State archived: $archive"
